hooks.command:
f=$(jq -r '.tool_input.file_path // empty'); case "$f" in
  */public/scad/*.scad) cat <<'JSON'
{"hookSpecificOutput": {"hookEventName": "PreToolUse", "permissionDecision": "deny", "permissionDecisionReason": "public/scad/**.scad is generated by sync-scad from the canonical narrowstacks/DarkroomSCAD repo and is overwritten on every build. Do NOT edit it here. Edit the matching file under ../DarkroomSCAD/negative-carriers/ instead, push to narrowstacks/DarkroomSCAD, then run: npm run sync:scad. See CLAUDE.md."}}
JSON
  ;;
  */generated/*.json|*/public/outlines/*.svg) cat <<'JSON'
{"hookSpecificOutput": {"hookEventName": "PreToolUse", "permissionDecision": "deny", "permissionDecisionReason": "This is a GENERATED artifact (generated/*.json or public/outlines/*.svg), not editable source. Do NOT hand-edit it. Regenerate instead: `npm run gen:outlines` for the outline JSON + SVGs, or `npm run sync:scad` for generated/param-schema.json. To change outline geometry, edit the upstream SCAD or scripts/gen-carrier-outlines.ts. The typed loaders src/lib/outline/*.ts that import the JSON ARE editable. See CLAUDE.md."}}
JSON
  ;;
esac
